// Fictional multi-instance records. Native popup/postback handlers are not executed.
(() => {
 const proposed=document.body.dataset.variant==='multi-proposed';
 const seed=[{status:'Active',severity:'Information',message:'Contact prefers email updates.'},{status:'Active',severity:'Urgent',message:'Follow up on the outstanding enquiry.'},{status:'Active',severity:'Warning',message:'Confirm contact details at next interaction.'}];
 let rows=seed.map((row,i)=>({...row,id:i+1,updated:'9/09/2026 4:57 PM'})),nextId=4,editingId=null,deleteId=null,trigger;
 let sortKey='status',sortDirection='ascending';
 const tbody=document.querySelector('tbody'),editor=document.querySelector('#row-editor'),form=editor.querySelector('form'),confirmation=document.querySelector('#row-delete'),feedback=document.querySelector('[role=status]');
 const size=()=>parent.postMessage({type:'data-panel-size',height:Math.max(520,document.body.scrollHeight+8)},'*');
 function iconButton(label,icon,handler,danger=false){const button=document.createElement('button');button.type='button';button.title=label;button.setAttribute('aria-label',label);button.className=proposed?'TextButton us-icon-button'+(danger?' DangerButton':''):'native-action'+(danger?' native-delete':'');const glyph=document.createElement('i');glyph.className='ti ti-'+(danger&&!proposed?'x':icon);glyph.setAttribute('aria-hidden','true');button.append(glyph);button.addEventListener('click',()=>handler(button));return button;}
 function openEditor(id,button){editingId=id;trigger=button;const row=rows.find(r=>r.id===id)||{status:'Active',severity:'Information',message:''};form.reset();for(const name of ['status','severity','message'])form.elements[name].value=row[name];document.querySelector('#row-title').textContent=id===null?'Add alert':'Edit alert';editor.showModal();form.elements.message.focus();}
 function render(){
  document.querySelectorAll('[data-sort]').forEach(link=>{const active=link.dataset.sort===sortKey;link.parentElement.classList.toggle('rgSorted',active);link.parentElement.setAttribute('aria-sort',active?sortDirection:'none');});
  const ordered=[...rows].sort((a,b)=>{const av=sortKey==='updated'?(a.updated==='Just now'?1:0):a[sortKey],bv=sortKey==='updated'?(b.updated==='Just now'?1:0):b[sortKey];const result=typeof av==='number'?av-bv:String(av).localeCompare(String(bv),undefined,{numeric:true,sensitivity:'base'});return result*(sortDirection==='ascending'?1:-1)||a.id-b.id;});
  tbody.replaceChildren();ordered.forEach(row=>{const tr=document.createElement('tr');tr.className='rgRow';for(const name of ['status','severity','message','updated']){const td=document.createElement('td');td.textContent=row[name];tr.append(td);}const actions=document.createElement('td');actions.className='row-actions';actions.append(iconButton('Edit alert '+row.id,'pencil',button=>openEditor(row.id,button)),iconButton('Delete alert '+row.id,'trash',button=>{deleteId=row.id;trigger=button;document.querySelector('#delete-description').textContent='Delete this example alert: '+row.message;confirmation.showModal();},true));tr.append(actions);tbody.append(tr);});if(!rows.length){const tr=document.createElement('tr'),td=document.createElement('td');td.colSpan=5;td.textContent='No alerts. Use Add to create an example row.';tr.append(td);tbody.append(tr);}requestAnimationFrame(size);}
 document.querySelectorAll('[data-sort]').forEach(link=>link.addEventListener('click',event=>{event.preventDefault();sortDirection=sortKey===link.dataset.sort&&sortDirection==='ascending'?'descending':'ascending';sortKey=link.dataset.sort;render();feedback.textContent='Sorted by '+link.textContent+', '+sortDirection+'.';}));
 document.querySelector('[data-add]').addEventListener('click',event=>openEditor(null,event.currentTarget));
 form.addEventListener('submit',event=>{event.preventDefault();if(!form.reportValidity())return;const values=Object.fromEntries(new FormData(form));if(editingId===null)rows.push({...values,id:nextId++,updated:'Just now'});else Object.assign(rows.find(r=>r.id===editingId),values,{updated:'Just now'});editor.close();render();feedback.textContent='Row saved in this example only.';document.querySelector('[data-add]').focus();});
 document.querySelector('[data-cancel-row]').addEventListener('click',()=>editor.close());
 editor.addEventListener('close',()=>{if(trigger?.isConnected)trigger.focus();});
 document.querySelector('[data-cancel-delete]').addEventListener('click',()=>confirmation.close());
 document.querySelector('[data-confirm-delete]').addEventListener('click',()=>{rows=rows.filter(r=>r.id!==deleteId);confirmation.close();render();feedback.textContent='Example row deleted. Reset examples restores it.';document.querySelector('[data-add]').focus();});
 confirmation.addEventListener('close',()=>{if(trigger?.isConnected)trigger.focus();});
 const settings=document.querySelector('#multi-settings');document.querySelector('[data-settings]').addEventListener('click',()=>settings.showModal());document.querySelector('[data-close-settings]').addEventListener('click',()=>settings.close());
 window.addEventListener('message',event=>{if(event.source!==parent||event.data?.type!=='data-panel-command'||event.data.action!=='reset')return;rows=seed.map((row,i)=>({...row,id:i+1,updated:'9/09/2026 4:57 PM'}));nextId=4;sortKey='status';sortDirection='ascending';feedback.textContent='';editor.close();confirmation.close();render();});
 new ResizeObserver(size).observe(document.body);render();
})();
